'use strict';
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
(async()=>{try{const response=await fetch('/api/plans');if(!response.ok)throw Error();const catalog=await response.json();document.getElementById('planOptions').innerHTML=catalog.plans.map(plan=>'<article class="plan"><span class="eyebrow">'+escapeHTML(plan.id==='growth'?'ROOM TO GROW':plan.id==='starter'?'START WITH CLARITY':'BUILD TOGETHER')+'</span><h3>'+escapeHTML(plan.name)+'</h3><p>'+escapeHTML(plan.tagline)+'</p>'+(plan.prices.length?'<div class="price-list">'+plan.prices.map(p=>'<p><strong>'+escapeHTML(Pulse.formatMoney(p.amount,p.currency))+'</strong> / '+(p.interval==='year'?'year':'month')+'</p>').join('')+'</div>':'<div class="plan-price">14 days free<small>Paid pricing available before launch</small></div>')+'<ul>'+plan.features.map(f=>'<li>'+escapeHTML(f)+'</li>').join('')+'</ul><a class="button dark" href="/signup?plan='+encodeURIComponent(plan.id)+'">Try '+escapeHTML(plan.name)+' ↗</a></article>').join('');document.getElementById('pricingNote').textContent=catalog.ready?'No card needed to start your trial. Choose a paid subscription from your workspace.':'No card needed to start. Paid subscriptions will open when service pricing is configured.';}catch{document.getElementById('planOptions').innerHTML='<p>Plans are temporarily unavailable. <a href="/signup">Start your 14-day trial</a> or check back shortly.</p>';}})();
